import os
import base64
from flask import Flask, request, jsonify, send_file
from flask_cors import CORS
from config import Config
from models import db, Barcode
from barcode_service import (
    validate_input,
    generate_barcode_image,
    export_as_jpeg,
    export_as_pdf,
    BARCODE_TYPES,
)
import io


def create_app():
    app = Flask(__name__)
    app.config.from_object(Config)
    CORS(app)
    db.init_app(app)

    os.makedirs(app.config.get("UPLOAD_FOLDER", "uploads"), exist_ok=True)

    with app.app_context():
        db.create_all()

    return app


app = create_app()


@app.route("/api/barcode-types", methods=["GET"])
def get_barcode_types():
    """Return available barcode types."""
    types = [
        {"id": "code128", "name": "Code 128", "description": "Alphanumeric barcode"},
        {"id": "ean13", "name": "EAN-13", "description": "13-digit product barcode"},
        {"id": "qr", "name": "QR Code", "description": "2D barcode for text/URLs"},
    ]
    return jsonify(types)


@app.route("/api/validate", methods=["POST"])
def validate_data():
    """Validate barcode input data in real-time."""
    payload = request.get_json()
    if not payload:
        return jsonify({"valid": False, "errors": ["No data provided."]}), 400

    barcode_type = payload.get("barcode_type", "").strip()
    data = payload.get("data", "").strip()

    errors = validate_input(barcode_type, data)
    return jsonify({"valid": len(errors) == 0, "errors": errors})


@app.route("/api/generate", methods=["POST"])
def generate_barcode():
    """Generate a barcode and return as base64 PNG."""
    payload = request.get_json()
    if not payload:
        return jsonify({"error": "No data provided."}), 400

    barcode_type = payload.get("barcode_type", "").strip()
    data = payload.get("data", "").strip()
    options = payload.get("options", {})

    errors = validate_input(barcode_type, data)
    if errors:
        return jsonify({"error": errors[0], "errors": errors}), 400

    try:
        image_bytes = generate_barcode_image(barcode_type, data, options)
        image_b64 = base64.b64encode(image_bytes).decode("utf-8")
        return jsonify({
            "image": f"data:image/png;base64,{image_b64}",
            "barcode_type": barcode_type,
            "data": data,
        })
    except Exception as e:
        return jsonify({"error": f"Failed to generate barcode: {str(e)}"}), 500


@app.route("/api/export/<fmt>", methods=["POST"])
def export_barcode(fmt):
    """Export barcode in the specified format (jpeg or pdf)."""
    if fmt not in ("jpeg", "pdf"):
        return jsonify({"error": "Unsupported format. Use 'jpeg' or 'pdf'."}), 400

    payload = request.get_json()
    if not payload:
        return jsonify({"error": "No data provided."}), 400

    barcode_type = payload.get("barcode_type", "").strip()
    data = payload.get("data", "").strip()
    options = payload.get("options", {})

    errors = validate_input(barcode_type, data)
    if errors:
        return jsonify({"error": errors[0], "errors": errors}), 400

    try:
        image_bytes = generate_barcode_image(barcode_type, data, options)

        if fmt == "jpeg":
            output_bytes = export_as_jpeg(image_bytes)
            mimetype = "image/jpeg"
            filename = "barcode.jpg"
        else:
            output_bytes = export_as_pdf(image_bytes)
            mimetype = "application/pdf"
            filename = "barcode.pdf"

        return send_file(
            io.BytesIO(output_bytes),
            mimetype=mimetype,
            as_attachment=True,
            download_name=filename,
        )
    except Exception as e:
        return jsonify({"error": f"Export failed: {str(e)}"}), 500


@app.route("/api/barcodes", methods=["GET"])
def list_barcodes():
    """List all saved barcodes."""
    barcodes = Barcode.query.order_by(Barcode.created_at.desc()).all()
    return jsonify([b.to_dict() for b in barcodes])


@app.route("/api/barcodes", methods=["POST"])
def save_barcode():
    """Save a barcode to the database."""
    payload = request.get_json()
    if not payload:
        return jsonify({"error": "No data provided."}), 400

    name = payload.get("name", "").strip()
    barcode_type = payload.get("barcode_type", "").strip()
    data = payload.get("data", "").strip()
    options = payload.get("options", {})

    if not name:
        return jsonify({"error": "Name is required."}), 400

    errors = validate_input(barcode_type, data)
    if errors:
        return jsonify({"error": errors[0], "errors": errors}), 400

    try:
        image_bytes = generate_barcode_image(barcode_type, data, options)

        barcode_entry = Barcode(
            name=name,
            barcode_type=barcode_type,
            data=data,
            options=options,
            image_data=image_bytes,
        )
        db.session.add(barcode_entry)
        db.session.commit()

        return jsonify(barcode_entry.to_dict()), 201
    except Exception as e:
        db.session.rollback()
        return jsonify({"error": f"Failed to save barcode: {str(e)}"}), 500


@app.route("/api/barcodes/<int:barcode_id>", methods=["GET"])
def get_barcode(barcode_id):
    """Get a saved barcode by ID with its image."""
    barcode_entry = db.session.get(Barcode, barcode_id)
    if not barcode_entry:
        return jsonify({"error": "Barcode not found."}), 404

    result = barcode_entry.to_dict()
    if barcode_entry.image_data:
        result["image"] = (
            f"data:image/png;base64,{base64.b64encode(barcode_entry.image_data).decode()}"
        )
    return jsonify(result)


@app.route("/api/barcodes/<int:barcode_id>", methods=["DELETE"])
def delete_barcode(barcode_id):
    """Delete a saved barcode."""
    barcode_entry = db.session.get(Barcode, barcode_id)
    if not barcode_entry:
        return jsonify({"error": "Barcode not found."}), 404

    db.session.delete(barcode_entry)
    db.session.commit()
    return jsonify({"message": "Barcode deleted successfully."})


if __name__ == "__main__":
    app.run(debug=True, port=5000)

