const express = require('express');
const http = require('http');
const { WebSocketServer } = require('ws');
const path = require('path');
const Datastore = require('nedb-promises');

const app = express();
const server = http.createServer(app);
const wss = new WebSocketServer({ server });

const db = {
  games: Datastore.create({ filename: path.join(__dirname, 'data', 'games.db'), autoload: true }),
  players: Datastore.create({ filename: path.join(__dirname, 'data', 'players.db'), autoload: true }),
};

app.use(express.static(path.join(__dirname, 'public')));
app.use(express.json());

function generateId() {
  return Math.random().toString(36).substring(2, 8).toUpperCase();
}

function checkWinner(board) {
  const lines = [
    [0, 1, 2], [3, 4, 5], [6, 7, 8],
    [0, 3, 6], [1, 4, 7], [2, 5, 8],
    [0, 4, 8], [2, 4, 6],
  ];
  for (const [a, b, c] of lines) {
    if (board[a] && board[a] === board[b] && board[a] === board[c]) {
      return { winner: board[a], line: [a, b, c] };
    }
  }
  if (board.every(cell => cell !== null)) {
    return { winner: 'draw', line: null };
  }
  return null;
}

const gameClients = new Map();

function broadcast(gameId, message) {
  const clients = gameClients.get(gameId) || [];
  const payload = JSON.stringify(message);
  for (const ws of clients) {
    if (ws.readyState === ws.OPEN) ws.send(payload);
  }
}

async function sendGameState(gameId) {
  const game = await db.games.findOne({ gameId });
  if (!game) return;
  broadcast(gameId, { type: 'game_state', game });
}

wss.on('connection', (ws) => {
  let currentGameId = null;
  let currentPlayerId = null;

  ws.on('message', async (raw) => {
    let msg;
    try { msg = JSON.parse(raw); } catch { return; }

    if (msg.type === 'create_game') {
      const gameId = generateId();
      const playerId = generateId();
      const game = {
        gameId,
        board: Array(9).fill(null),
        players: { X: playerId, O: null },
        currentTurn: 'X',
        status: 'waiting',
        winner: null,
        winLine: null,
        createdAt: new Date().toISOString(),
        moves: [],
      };
      await db.games.insert(game);
      await db.players.insert({ playerId, name: msg.name || 'Player 1', gameId, symbol: 'X' });

      currentGameId = gameId;
      currentPlayerId = playerId;
      gameClients.set(gameId, [ws]);

      ws.send(JSON.stringify({ type: 'game_created', gameId, playerId, symbol: 'X', game }));
    }

    if (msg.type === 'join_game') {
      const game = await db.games.findOne({ gameId: msg.gameId });
      if (!game) return ws.send(JSON.stringify({ type: 'error', message: 'Game not found' }));
      if (game.status !== 'waiting') return ws.send(JSON.stringify({ type: 'error', message: 'Game already in progress or finished' }));

      const playerId = generateId();
      await db.games.update({ gameId: msg.gameId }, {
        $set: { 'players.O': playerId, status: 'playing' },
      });
      await db.players.insert({ playerId, name: msg.name || 'Player 2', gameId: msg.gameId, symbol: 'O' });

      currentGameId = msg.gameId;
      currentPlayerId = playerId;
      const clients = gameClients.get(msg.gameId) || [];
      clients.push(ws);
      gameClients.set(msg.gameId, clients);

      ws.send(JSON.stringify({ type: 'game_joined', gameId: msg.gameId, playerId, symbol: 'O' }));
      await sendGameState(msg.gameId);
    }

    if (msg.type === 'make_move') {
      const game = await db.games.findOne({ gameId: currentGameId });
      if (!game || game.status !== 'playing') return;

      const playerSymbol = game.players.X === currentPlayerId ? 'X' : 'O';
      if (game.currentTurn !== playerSymbol) return ws.send(JSON.stringify({ type: 'error', message: 'Not your turn' }));

      const cell = msg.cell;
      if (cell < 0 || cell > 8 || game.board[cell] !== null) return ws.send(JSON.stringify({ type: 'error', message: 'Invalid move' }));

      const newBoard = [...game.board];
      newBoard[cell] = playerSymbol;

      const move = { player: playerSymbol, cell, timestamp: new Date().toISOString() };
      const result = checkWinner(newBoard);

      const update = {
        board: newBoard,
        currentTurn: playerSymbol === 'X' ? 'O' : 'X',
        moves: [...game.moves, move],
      };

      if (result) {
        update.status = 'finished';
        update.winner = result.winner;
        update.winLine = result.line;
      }

      await db.games.update({ gameId: currentGameId }, { $set: update });
      await sendGameState(currentGameId);
    }

    if (msg.type === 'rematch') {
      const oldGame = await db.games.findOne({ gameId: currentGameId });
      if (!oldGame || oldGame.status !== 'finished') return;

      await db.games.update({ gameId: currentGameId }, {
        $set: {
          board: Array(9).fill(null),
          currentTurn: 'X',
          status: 'playing',
          winner: null,
          winLine: null,
          moves: [],
        },
      });
      await sendGameState(currentGameId);
    }
  });

  ws.on('close', () => {
    if (currentGameId) {
      const clients = gameClients.get(currentGameId) || [];
      gameClients.set(currentGameId, clients.filter(c => c !== ws));
      broadcast(currentGameId, { type: 'player_disconnected' });
    }
  });
});

