  background: #0f0f23;
  color: #e0e0e0;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
}

#app {
  text-align: center;
  width: 100%;
  max-width: 500px;
  padding: 20px;
}

h1 {
  font-size: 2.2rem;
  margin-bottom: 30px;
  background: linear-gradient(135deg, #00d2ff, #7a5cff);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  letter-spacing: 2px;
}

.hidden { display: none !important; }

.card {
  background: #1a1a36;
  border-radius: 16px;
  padding: 32px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

input {
  width: 100%;
  padding: 14px 18px;
  border: 2px solid #2a2a4a;
  border-radius: 10px;
  background: #12122a;
  color: #e0e0e0;
  font-size: 1rem;
