  outline: none;
  transition: border-color 0.2s;
}

input:focus { border-color: #7a5cff; }
input::placeholder { color: #555; }

button {
  width: 100%;
  padding: 14px;
  border: none;
  border-radius: 10px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: transform 0.15s, box-shadow 0.15s;
