}

button:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 20px rgba(122, 92, 255, 0.4);
}

button:active { transform: translateY(0); }

.divider {
  margin: 20px 0;
  color: #555;
  font-size: 0.85rem;
  position: relative;
}

.divider::before,
.divider::after {
  content: '';
  position: absolute;
  top: 50%;
  width: 30%;
  height: 1px;
  background: #2a2a4a;
}
.divider::before { left: 0; }
.divider::after { right: 0; }

.code {
  font-size: 1.8rem;
  font-weight: 700;
  color: #00d2ff;
  letter-spacing: 6px;
  margin: 16px 0;
}

.hint {
  color: #666;
  font-size: 0.85rem;
}

.game-info {
  display: flex;
