let ws;
let mySymbol = null;
let myPlayerId = null;
let currentGameId = null;

function connect() {
  const protocol = location.protocol === 'https:' ? 'wss:' : 'ws:';
  ws = new WebSocket(`${protocol}//${location.host}`);

  ws.onmessage = (event) => {
    const msg = JSON.parse(event.data);
    handleMessage(msg);
  };

  ws.onclose = () => {
    setTimeout(connect, 2000);
  };
}

function handleMessage(msg) {
  switch (msg.type) {
    case 'game_created':
      myPlayerId = msg.playerId;
      mySymbol = msg.symbol;
      currentGameId = msg.gameId;
      document.getElementById('displayCode').textContent = msg.gameId;
      showScreen('waiting');
      break;

    case 'game_joined':
      myPlayerId = msg.playerId;
      mySymbol = msg.symbol;
      currentGameId = msg.gameId;
      showScreen('game');
      break;

    case 'game_state':
      renderGame(msg.game);
      if (msg.game.status === 'playing' || msg.game.status === 'finished') {
        showScreen('game');
      }
      break;

    case 'player_disconnected':
      document.getElementById('disconnected').classList.remove('hidden');
      break;

    case 'error':
      alert(msg.message);
      break;
  }
}

function showScreen(name) {
  document.querySelectorAll('.screen').forEach(s => s.classList.add('hidden'));
  document.getElementById(name).classList.remove('hidden');
}

function createGame() {
  const name = document.getElementById('playerName').value.trim() || 'Player 1';
  ws.send(JSON.stringify({ type: 'create_game', name }));
}

function joinGame() {
  const code = document.getElementById('gameCode').value.trim().toUpperCase();
  const name = document.getElementById('playerName').value.trim() || 'Player 2';
  if (!code) return alert('Enter a game code');
  ws.send(JSON.stringify({ type: 'join_game', gameId: code, name }));
}

function makeMove(cell) {
  ws.send(JSON.stringify({ type: 'make_move', cell }));
}

function rematch() {
  document.getElementById('gameOver').classList.add('hidden');
  ws.send(JSON.stringify({ type: 'rematch' }));
}

function backToLobby() {
  location.reload();
}

function renderGame(game) {
  const cells = document.querySelectorAll('.cell');
  cells.forEach((cell, i) => {
    const val = game.board[i];
    cell.textContent = val || '';
    cell.className = 'cell';
    if (val) cell.classList.add('taken', val.toLowerCase());
    if (game.winLine && game.winLine.includes(i)) cell.classList.add('win');
  });

  const isMyTurn = game.currentTurn === mySymbol;
  const indicator = document.getElementById('turnIndicator');

  if (game.status === 'playing') {
    indicator.textContent = isMyTurn ? 'Your turn' : "Opponent's turn";
  }

  document.getElementById('playerX').classList.toggle('active', game.currentTurn === 'X' && game.status === 'playing');
  document.getElementById('playerO').classList.toggle('active', game.currentTurn === 'O' && game.status === 'playing');

  document.getElementById('gameOver').classList.add('hidden');
  document.getElementById('disconnected').classList.add('hidden');

  if (game.status === 'finished') {
    const resultEl = document.getElementById('resultText');
    if (game.winner === 'draw') {
      resultEl.textContent = "It's a draw!";
    } else if (game.winner === mySymbol) {
      resultEl.textContent = 'You win!';
    } else {
      resultEl.textContent = 'You lose!';
    }
    document.getElementById('gameOver').classList.remove('hidden');
  }
}

document.getElementById('gameCode').addEventListener('keydown', (e) => {
  if (e.key === 'Enter') joinGame();
});

document.getElementById('playerName').addEventListener('keydown', (e) => {
  if (e.key === 'Enter') {
    const code = document.getElementById('gameCode').value.trim();
    if (code) joinGame();
    else createGame();
  }
});

connect();

