class MetricModel:
    COLLECTION = "metrics"

    @staticmethod
    def collection():
        return db[MetricModel.COLLECTION]

    @staticmethod
    def insert(server_id: str, payload: dict) -> dict:
        """
        payload expected shape:
        {
          "cpu": {"percent": float, "load_avg": [1m,5m,15m], "core_count": int},
          "memory": {"total": int, "used": int, "percent": float},
          "swap": {"total": int, "used": int, "percent": float},
          "disk": [{"device": str, "mountpoint": str, "total": int, "used": int, "percent": float}],
          "network": {"bytes_sent": int, "bytes_recv": int, "packets_sent": int, "packets_recv": int},
          "processes": int,
          "uptime": float,
        }
        """
        doc = {
            "server_id": server_id,
            "timestamp": datetime.now(timezone.utc),
            **payload,
        }
        result = MetricModel.collection().insert_one(doc)
        doc["_id"] = result.inserted_id
        return doc

    @staticmethod
    def get_latest(server_id: str) -> dict | None:
        return MetricModel.collection().find_one(
            {"server_id": server_id}, sort=[("timestamp", -1)]
        )

    @staticmethod
    def get_range(server_id: str, minutes: int = 60, limit: int = 120) -> list:
        since = datetime.now(timezone.utc) - timedelta(minutes=minutes)
        cursor = (
            MetricModel.collection()
            .find({"server_id": server_id, "timestamp": {"$gte": since}})
            .sort("timestamp", 1)
            .limit(limit)
        )
        return list(cursor)

    @staticmethod
    def get_aggregated(server_id: str, hours: int = 24, bucket_minutes: int = 5) -> list:
        """Return time-bucketed averages for charting historical views."""
        since = datetime.now(timezone.utc) - timedelta(hours=hours)
        pipeline = [
            {"$match": {"server_id": server_id, "timestamp": {"$gte": since}}},
            {
                "$group": {
                    "_id": {
                        "$toDate": {
                            "$subtract": [
                                {"$toLong": "$timestamp"},
                                {
                                    "$mod": [
                                        {"$toLong": "$timestamp"},
                                        bucket_minutes * 60 * 1000,
                                    ]
                                },
                            ]
                        }
                    },
                    "avg_cpu": {"$avg": "$cpu.percent"},
                    "avg_mem": {"$avg": "$memory.percent"},
                    "avg_swap": {"$avg": "$swap.percent"},
                    "avg_net_sent": {"$avg": "$network.bytes_sent"},
                    "avg_net_recv": {"$avg": "$network.bytes_recv"},
                    "count": {"$sum": 1},
                }
            },
            {"$sort": {"_id": 1}},
        ]
        return list(MetricModel.collection().aggregate(pipeline))

    @staticmethod
    def serialize(metric: dict) -> dict:
        return {
            "id": str(metric["_id"]),
            "server_id": metric["server_id"],
            "timestamp": metric["timestamp"].isoformat(),
            "cpu": metric.get("cpu", {}),
            "memory": metric.get("memory", {}),
            "swap": metric.get("swap", {}),
            "disk": metric.get("disk", []),
            "network": metric.get("network", {}),
            "processes": metric.get("processes", 0),
            "uptime": metric.get("uptime", 0),
        }

