def parse_mdignore(content: str) -> set:
    """
    Parse .mdignore file content and return set of patterns to ignore.

    Args:
        content: Content of .mdignore file

    Returns:
        Set of patterns to ignore
    """
    patterns = set()
    for line in content.split('\n'):
        line = line.strip()
        if line and not line.startswith('#'):
            patterns.add(line)
    return patterns


def should_ignore_file(filename: str, patterns: set) -> bool:
    """
    Check if file should be ignored based on patterns.

    Args:
        filename: Name of the file
        patterns: Set of patterns to match

    Returns:
        True if file should be ignored
    """
    for pattern in patterns:
        if pattern in filename or filename.endswith(pattern):
            return True
    return False


async def process_markdown_files(
    files: List[UploadFile],
    mdignore_patterns: set = None
) -> tuple[List[FileAnalysis], List[str]]:
    """
    Process multiple markdown files and calculate metrics.

    Args:
        files: List of uploaded files
        mdignore_patterns: Set of patterns to ignore

    Returns:
        Tuple of (list of FileAnalysis, list of ignored files)
    """
    if mdignore_patterns is None:
        mdignore_patterns = set()

    analyses = []
    ignored_files = []

    for file in files:
        # Check if file should be ignored
        if should_ignore_file(file.filename, mdignore_patterns):
            ignored_files.append(file.filename)
            continue

        # Only process markdown files
        if not file.filename.endswith('.md'):
            ignored_files.append(file.filename)
            continue

        try:
            content = await file.read()
            file_size = len(content)
            text_content = content.decode('utf-8', errors='ignore')

            # Extract plain text from markdown
            plain_text = extract_text_from_markdown(text_content)

            # Calculate metrics
            metrics_data = calculate_readability_metrics(plain_text)
            metrics = ReadabilityMetrics(**metrics_data)

            # Create file analysis
            analysis = FileAnalysis(
                filename=file.filename,
                file_path=file.filename,
                metrics=metrics,
                file_size_bytes=file_size
            )
            analyses.append(analysis)
        except Exception as e:
            print(f"Error processing file {file.filename}: {e}")
            ignored_files.append(file.filename)

    return analyses, ignored_files


