@app.post("/api/analyze")
async def analyze_endpoint(
    files: List[UploadFile] = File(...),
    mdignore_file: Optional[UploadFile] = File(None)
):
    """
    Analyze uploaded Markdown files.

    Args:
        files: List of markdown files to analyze
        mdignore_file: Optional .mdignore file with patterns to ignore

    Returns:
        Analysis results with metrics for each file
    """
    if not files:
        raise HTTPException(status_code=400, detail="No files provided")

    # Parse mdignore patterns if provided
    mdignore_patterns = set()
    if mdignore_file:
        try:
            content = await mdignore_file.read()
            mdignore_content = content.decode('utf-8', errors='ignore')
            mdignore_patterns = parse_mdignore(mdignore_content)
        except Exception as e:
            print(f"Error reading .mdignore file: {e}")

    # Process files
    try:
        analyses, ignored_files = await process_markdown_files(files, mdignore_patterns)

        if not analyses:
            raise HTTPException(
                status_code=400,
                detail="No valid markdown files found in the upload"
            )

        # Gather metrics for aggregation
        metrics_list = [analysis.metrics.model_dump() for analysis in analyses]
        summary_metrics = aggregate_metrics(metrics_list)

        # Create analysis result
        analysis_id = str(uuid.uuid4())
        result = AnalysisResult(
            analysis_id=analysis_id,
            files_analyzed=analyses,
            summary_metrics=summary_metrics,
            ignored_files=ignored_files
        )

        # Save to database
        analysis_dict = {
            "analysis_id": result.analysis_id,
            "analysis_date": result.analysis_date,
            "files_analyzed": [
                {
                    "filename": a.filename,
                    "file_path": a.file_path,
                    "metrics": a.metrics.model_dump(),
                    "analysis_date": a.analysis_date.isoformat(),
                    "file_size_bytes": a.file_size_bytes
                }
                for a in result.files_analyzed
            ],
            "summary_metrics": result.summary_metrics,
            "ignored_files": result.ignored_files
        }

        db_service.save_analysis(analysis_dict)

        # Return result
        return {
            "analysis_id": result.analysis_id,
            "analysis_date": result.analysis_date.isoformat(),
            "files_analyzed": [
                {
                    "filename": a.filename,
                    "file_path": a.file_path,
                    "metrics": a.metrics.model_dump(),
                    "analysis_date": a.analysis_date.isoformat(),
                    "file_size_bytes": a.file_size_bytes
                }
                for a in result.files_analyzed
            ],
            "summary_metrics": result.summary_metrics,
            "ignored_files": result.ignored_files
        }

    except HTTPException:
        raise
    except Exception as e:
        print(f"Error during analysis: {e}")
        raise HTTPException(status_code=500, detail=f"Analysis failed: {str(e)}")


@app.get("/api/analyses")
async def list_analyses(limit: int = 10):
    """
    List recent analyses.

    Args:
        limit: Maximum number of analyses to return

    Returns:
        List of analysis summaries
    """
    analyses = db_service.list_analyses(limit)
    return {"analyses": analyses, "total": len(analyses)}


@app.get("/api/analyses/{analysis_id}")
async def get_analysis(analysis_id: str):
    """
    Get specific analysis result.

    Args:
        analysis_id: ID of the analysis

    Returns:
        Analysis result
    """
    analysis = db_service.get_analysis(analysis_id)
    if not analysis:
        raise HTTPException(status_code=404, detail="Analysis not found")
    return analysis


@app.delete("/api/analyses/{analysis_id}")
async def delete_analysis(analysis_id: str):
    """
    Delete specific analysis.

    Args:
        analysis_id: ID of the analysis to delete

    Returns:
        Success message
    """
    success = db_service.delete_analysis(analysis_id)
    if not success:
        raise HTTPException(status_code=404, detail="Analysis not found")
    return {"message": "Analysis deleted successfully"}


@app.on_event("shutdown")
async def shutdown_event():
    """Close database connection on shutdown."""
    db_service.close()


if __name__ == "__main__":
    import uvicorn
    uvicorn.run(
        "main:app",
        host="0.0.0.0",
        port=8000,
        reload=True
    )

